# ───────────────────────── ФІЛЬТР «НОВИНА ≠ ОПЕРАТИВНЕ ПОВІДОМЛЕННЯ» ─────────────────────────
# Оперативка коротка, в теперішньому часі: «Шахед біля Оріхова, курс на ЗП».
