INDEX_MARK = b"v2-tex"

def load_index(path):
    import zlib, base64
    try:
        with open(path, "rb") as fp:
            body = fp.read()
        if INDEX_MARK in body:
            return body
    except OSError:
        pass
    return zlib.decompress(base64.b64decode("".join(_INDEX_B64.split())))

async def serve_index(request):
    D = os.path.dirname(os.path.abspath(__file__))
    return web.Response(
        body=load_index(os.path.join(D, "index.html")),
        content_type="text/html",
        headers={"Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"}
    )

async def serve_no_cache_file(path, content_type):
    with open(path, "rb") as fp:
        body = fp.read()
    return web.Response(
        body=body,
        content_type=content_type,
        headers={"Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"}
    )

async def main():
    conn = aiohttp.TCPConnector(limit=35, ttl_dns_cache=300)
    s = aiohttp.ClientSession(connector=conn)
    app = web.Application()
    app["session"] = s
    D = os.path.dirname(os.path.abspath(__file__))
    f = lambda n: (lambda r: web.FileResponse(os.path.join(D, n)))
    app.add_routes([
        web.get("/", serve_index),
        web.get("/3d", lambda r: serve_no_cache_file(os.path.join(D, "radar3d.html"), "text/html")),
        web.get("/events", events),
        web.get("/state", state_endpoint),
        web.get("/api/oblasts", oblasts_endpoint),
        web.post("/sim", sim_endpoint),
        web.get("/manifest.json", f("manifest.json")),
        web.get("/sw.js", lambda r: serve_no_cache_file(os.path.join(D, "sw.js"), "application/javascript")),
        web.get("/icon-192.png", f("icon-192.png")),
        web.get("/icon-512.png", f("icon-512.png")),
        web.get("/health", lambda r: web.Response(text="ok")),
        web.get("/api/push/key", push_key),
        web.post("/api/push/subscribe", push_subscribe),
        web.post("/api/push/unsubscribe", push_unsubscribe),
        web.post("/api/push/test", push_test),
        web.get("/debug", lambda r: web.json_response({
            "places_count": len(PLACES),
            "realtime": rt_state,
            "channels": stats,
            "tracks": [
                dict(id=t["id"], sub=t["sub"], v=effective_speed(t), hdg=t["hdg"] and round(t["hdg"]),
                     unc=round(t["unc"], 1), n=t["n"], chs=sorted(t.get("channels") or []),
                     pos=[round(t["lat"], 3), round(t["lon"], 3)], frm=t["frm"], to=t["goal"] and t["goal"][0],
                     status=t.get("status_msg"), ended=bool(t.get("ended")),
                     shown=in_oblast(t["lat"], t["lon"]))
                for t in tracks.values()
            ],
            "log": log,
        }, dumps=lambda o: json.dumps(o, ensure_ascii=False, indent=1)))
    ])
    init_vapid()
    load_subs()
    for ch in CHANNELS:
        asyncio.create_task(poll(s, ch))
    asyncio.create_task(tick(s))
    asyncio.create_task(keepalive(s))
    asyncio.create_task(tg_realtime())
    asyncio.create_task(load_oblast_geo(s))
    asyncio.create_task(alerts_loop(s))
    run = web.AppRunner(app)
    await run.setup()
    await web.TCPSite(run, "0.0.0.0", int(os.getenv("PORT", 8080))).start()
    print(f"Оперативний Радар ZP v21 started on http://localhost:8080 | Channels: {CHANNELS}")
    await asyncio.Event().wait()

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except AttributeError:
        loop = asyncio.get_event_loop()
        loop.run_until_complete(main())